// LCD 1602 — text on a parallel display.
//
// The bundled LiquidCrystal library writes RS/E/D4-D7 four bits at a time;
// the display decodes the HD44780 commands and keeps the two lines.

#include <LiquidCrystal.h>

LiquidCrystal lcd(12, 11, 5, 4, 3, 2);

void setup() {
  lcd.begin(16, 2);
  lcd.print("Hello, Croquis!");
  lcd.setCursor(0, 1);
  lcd.print("LCD 1602 ready");
}

void loop() {
}
